use serde_json::{Value, Result};

pub fn solve(input: Value) -> Result<Value> {
    let input = input.as_object().ok_or("Input must be an object")?;
    let shift = input.get("shift").ok_or("Shift must be an integer")?.as_i64().ok_or("Shift must be an integer")?;
    let text = input.get("text").ok_or("Text must be a string")?.as_str().ok_or("Text must be a string")?;

    let mut result = String::new();
    for c in text.chars() {
        if c.is_ascii_lowercase() {
            let offset = (c as u8 - b'a' + shift as u8) % 26;
            result.push((offset + b'a') as char);
        } else {
            result.push(c);
        }
    }

    Ok(Value::String(result))
}
